WITH src AS (SELECT * FROM accounts WHERE (account_type NOT IN ('SAVINGS', 'LOAN', 'CHECKING') AND status <> 'FROZEN') OR opened_date < '2025-07-01'), customer_id_summary AS (SELECT customer_id, AVG(balance) AS avg_balance, MIN(opened_date) AS first_opened_date FROM src GROUP BY customer_id) SELECT * FROM customer_id_summary WHERE avg_balance < 37000 ORDER BY customer_id DESC, first_opened_date;
